<script setup>
import { ref, computed, onMounted, onUnmounted } from 'vue'
import { Activity, ArrowDownToLine, ArrowRight, Bell, BookOpen, Boxes, Check, CheckCheck, ChevronDown, ChevronRight, CircleHelp, CirclePlay, ClipboardCheck, Clock3, Code2, Database, FileCheck2, FileText, FlaskConical, FolderKanban, Gauge, GitBranch, LayoutDashboard, LogOut, Plus, RefreshCw, Search, Settings2, ShieldCheck, Sparkles, Square, Terminal, TriangleAlert, Users, X, XCircle, Zap } from 'lucide-vue-next'
const nav=[{id:'overview',name:'工作概览',icon:LayoutDashboard},{id:'requirements',name:'需求管理',icon:FileText},{id:'cases',name:'测试用例',icon:ClipboardCheck},{id:'ai',name:'AI 用例生成',icon:Sparkles},{id:'runs',name:'测试任务',icon:CirclePlay},{id:'reports',name:'报告与追踪',icon:Gauge},{id:'experiments',name:'对比实验',icon:FlaskConical},{id:'settings',name:'平台设置',icon:Settings2}]
const page=ref('overview'), authToken=ref(sessionStorage.getItem('aurora_token')||''),user=ref(null),loading=ref(false),busy=ref(false),toast=ref(null),modal=ref(null)
const projects=ref([]),projectId=ref(localStorage.getItem('aurora_project')||''),requirements=ref([]),cases=ref([]),runs=ref([]),generations=ref([]),experiments=ref([]),traceability=ref([]),stats=ref({}),config=ref({}),users=ref([]),audits=ref([])
const loginForm=ref({username:'admin',password:''}),loginError=ref(''),caseFilter=ref('all'),query=ref(''),selected=ref([]),generationResult=ref(null),detail=ref(null),selectedResult=ref(null),history=ref([]),editText=ref(''),form=ref({}),genForm=ref({requirement_id:'',method:'rules',count:4}),analysisMethod=ref('rules')
const currentProject=computed(()=>projects.value.find(x=>x.id===projectId.value)),pageTitle=computed(()=>nav.find(n=>n.id===page.value)?.name),canWrite=computed(()=>['admin','reviewer','tester'].includes(user.value?.role)),canReview=computed(()=>['admin','reviewer'].includes(user.value?.role))
const approved=computed(()=>cases.value.filter(c=>c.status==='approved')),filteredCases=computed(()=>cases.value.filter(c=>(caseFilter.value==='all'||c.status===caseFilter.value)&&(!query.value||c.body.title.toLowerCase().includes(query.value.toLowerCase())||c.body.requirement_points.join().includes(query.value))))
const activeRuns=computed(()=>runs.value.filter(r=>['queued','running','cancelling'].includes(r.status)).length),passRate=computed(()=>stats.value.pass_rate??0),genReq=computed(()=>requirements.value.find(r=>r.id===genForm.value.requirement_id))
const labels={pending:'待审核',approved:'已通过',rejected:'已驳回',queued:'排队中',running:'执行中',cancelling:'取消中',passed:'通过',failed:'失败',error:'执行异常',cancelled:'已取消',interrupted:'已中断',skipped:'已跳过',rules:'规则基线',direct_llm:'直接 LLM',constrained_llm:'规则约束 + LLM',admin:'管理员',reviewer:'审核员',tester:'测试工程师',viewer:'只读成员'}
const date=v=>v?new Date(v).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'—'
const duration=ms=>ms==null?'—':ms<1000?`${ms} ms`:`${(ms/1000).toFixed(1)} s`
const pct=v=>v==null?'—':`${(v*100).toFixed(1)}%`
function notify(message,error=false){toast.value={message,error};setTimeout(()=>{toast.value=null},5000)}
async function api(path,options={}){
 const r=await fetch('/api'+path,{...options,headers:{'Content-Type':'application/json',...(authToken.value?{Authorization:`Bearer ${authToken.value}`}:{})},body:options.body===undefined?undefined:JSON.stringify(options.body)})
 if(!r.ok){let data;try{data=await r.json()}catch{data={detail:r.statusText}};if(r.status===401){authToken.value='';sessionStorage.removeItem('aurora_token');user.value=null};throw new Error(Array.isArray(data.detail)?data.detail.map(e=>`${e.loc.slice(1).join('.')}: ${e.msg}`).join('；'):data.detail||'请求失败')}
 return r.json()
}
async function login(){busy.value=true;loginError.value='';try{const data=await api('/auth/login',{method:'POST',body:loginForm.value});authToken.value=data.access_token;user.value=data.user;sessionStorage.setItem('aurora_token',data.access_token);await initialize()}catch(e){loginError.value=e.message}finally{busy.value=false}}
function logout(){authToken.value='';user.value=null;sessionStorage.removeItem('aurora_token');modal.value=null}
async function initialize(){loading.value=true;try{user.value=await api('/auth/me');[projects.value,config.value]=await Promise.all([api('/projects'),api('/config')]);if(!projects.value.some(p=>p.id===projectId.value))projectId.value=projects.value[0]?.id||'';await reload();if(user.value.role==='admin'){[users.value,audits.value]=await Promise.all([api('/users'),api('/audit')])}}catch(e){notify(e.message,true)}finally{loading.value=false}}
async function reload(quiet=false){if(!projectId.value)return;if(!quiet)loading.value=true;try{localStorage.setItem('aurora_project',projectId.value);const suffix=`?project_id=${projectId.value}`;[requirements.value,cases.value,runs.value,stats.value,generations.value,experiments.value,traceability.value]=await Promise.all(['/requirements','/cases','/runs','/dashboard','/generations','/experiments','/traceability'].map(p=>api(p+suffix)));if(!requirements.value.some(r=>r.id===genForm.value.requirement_id))genForm.value.requirement_id=requirements.value[0]?.id||'';if(detail.value){const d=await api('/runs/'+detail.value.id);detail.value=d;if(selectedResult.value)selectedResult.value=d.results.find(r=>r.id===selectedResult.value.id)||null}}catch(e){if(!quiet)notify(e.message,true)}finally{if(!quiet)loading.value=false}}
function navigate(id){page.value=id;query.value='';selected.value=[]}
function open(type,data){form.value={};modal.value={type,data};if(type==='project')form.value=data?{name:data.name,description:data.description,base_url:data.base_url}:{name:'',description:'',base_url:'http://127.0.0.1:8000'};if(type==='requirement')form.value={title:'',content:'',points:'REQ-001 | '};if(type==='run')form.value={name:'Web 核心流程回归',browser:'chromium',repeat:1,case_ids:selected.value.filter(id=>approved.value.some(c=>c.id===id))};if(type==='review')form.value={decision:'approved',note:''};if(type==='user')form.value={username:'',password:'',role:'tester'};if(type==='case'){editText.value=JSON.stringify(data?.body||{title:'新测试用例',requirement_points:[requirements.value[0]?.points[0]?.id||'REQ-001'],preconditions:'被测系统可访问',steps:['打开页面','验证预期'],test_data:{},expected_result:'页面可见',priority:'P1',scenario:'custom',script:[{action:'goto',value:'/demo/'},{action:'expect_visible',locator:{by:'role',value:'heading',name:'Campus Lab 演示应用'}}]},null,2);form.value={requirement_id:data?.requirement_id||requirements.value[0]?.id,note:''};history.value=[];if(data)api('/cases/'+data.id+'/history').then(v=>history.value=v).catch(e=>notify(e.message,true))};if(type==='experiment')form.value={name:'',method:'rules',requirement_total:4,covered_points:0,generated:1,valid:0,executable:0,duplicates:0,defects_total:4,defects_detected:0,revision_seconds:0,generation_ms:0,evidence_ref:''}}
async function submit(){busy.value=true;try{const {type,data}=modal.value,f=form.value;if(type==='project'){await api('/projects'+(data?'/'+data.id:''),{method:data?'PUT':'POST',body:f});projects.value=await api('/projects');if(!data)projectId.value=projects.value[0].id}
if(type==='requirement'){const points=f.points.split('\n').filter(x=>x.trim()).map(line=>{const [id,...text]=line.split('|');return{id:id.trim(),text:text.join('|').trim()}});await api('/requirements',{method:'POST',body:{project_id:projectId.value,title:f.title,content:f.content,points}})}
if(type==='case'){const body=JSON.parse(editText.value);await api('/cases'+(data?'/'+data.id:''),{method:data?'PUT':'POST',body:data?{version:data.version,body,note:f.note}:{project_id:projectId.value,requirement_id:f.requirement_id,body}})}
if(type==='review'){await api('/cases/'+data.id+'/review',{method:'POST',body:{version:data.version,...f}})}
if(type==='run'){await api('/runs',{method:'POST',body:{project_id:projectId.value,...f}});page.value='runs'}
if(type==='user'){await api('/users',{method:'POST',body:f});users.value=await api('/users')}
if(type==='experiment'){const {name,method,...observations}=f;await api('/experiments',{method:'POST',body:{project_id:projectId.value,name,method,observations}})}
modal.value=null;notify(type==='run'?'任务已入队，浏览器将在后台执行':'已保存');await reload()}catch(e){notify(e.message,true)}finally{busy.value=false}}
async function generate(){busy.value=true;generationResult.value=null;try{generationResult.value=await api('/generations',{method:'POST',body:genForm.value});await reload();notify(`生成完成：新增 ${generationResult.value.cases.length} 条待审核用例`)}catch(e){notify(e.message,true)}finally{busy.value=false}}
async function runDetail(run){try{detail.value=await api('/runs/'+run.id);selectedResult.value=detail.value.results[0]||null;modal.value={type:'runDetail'}}catch(e){notify(e.message,true)}}
async function cancel(run){try{await api('/runs/'+run.id+'/cancel',{method:'POST'});await reload();notify('已提交取消请求')}catch(e){notify(e.message,true)}}
async function analyzeResult(){if(!selectedResult.value)return;busy.value=true;try{selectedResult.value.analysis=await api('/results/'+selectedResult.value.id+'/analysis',{method:'POST',body:{method:analysisMethod.value}});notify('分析完成，请结合证据复核')}catch(e){notify(e.message,true)}finally{busy.value=false}}
async function download(path,filename){try{const r=await fetch('/api'+path,{headers:{Authorization:`Bearer ${authToken.value}`}});if(!r.ok)throw new Error((await r.json()).detail);const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){notify(e.message,true)}}
function toggleAll(e){selected.value=e.target.checked?filteredCases.value.filter(c=>c.status==='approved').map(c=>c.id):[]}
const donutStyle=computed(()=>{const total=stats.value.executed||0;if(!total)return{background:'#e9ecf4'};const a=(stats.value.passed||0)/total*100,b=((stats.value.passed||0)+(stats.value.failed||0))/total*100;return{background:`conic-gradient(#6c59df 0% ${a}%, #eb9aa3 ${a}% ${b}%, #d7dce8 ${b}% 100%)`}})
const chartPoints=computed(()=>{const trend=stats.value.trend||[];return trend.map((r,i)=>`${50+i*(580/Math.max(trend.length-1,1))},${150-(r.passed/(r.passed+r.failed||1))*110}`).join(' ')})
let timer;onMounted(async()=>{if(authToken.value)await initialize();timer=setInterval(()=>{if(authToken.value&&projectId.value&&(activeRuns.value||modal.value?.type==='runDetail'))reload(true)},2000)});onUnmounted(()=>clearInterval(timer))
</script>

<template>
<div v-if="!user" class="login-shell"><div class="login-story"><div class="brand"><span class="brand-symbol"><Activity :size="23"/></span>Aurora<span>Test</span></div><div><span class="eyebrow light">FROM REQUIREMENTS TO CONFIDENCE</span><h1>让每一次发布，<br>都有据可依。</h1><p>把需求、智能生成与真实执行连接起来。<br>构建可审查、可验证、可追溯的测试工作流。</p><div class="login-flow"><FileText/><span></span><Sparkles/><span></span><ShieldCheck/><span></span><CirclePlay/></div></div><small>毕业设计 · 融合大语言模型的 Web 智能自动化测试平台</small></div><form class="login-card" @submit.prevent="login"><span class="mini-label">欢迎来到 AURORA TEST</span><h2>登录工作空间</h2><p class="muted">开始管理你的测试项目与自动化任务</p><label>用户名<input v-model="loginForm.username" autocomplete="username" required placeholder="输入用户名"></label><label>密码<input v-model="loginForm.password" type="password" autocomplete="current-password" required placeholder="输入密码"></label><p v-if="loginError" class="error-text">{{loginError}}</p><button class="btn primary wide" :disabled="busy">{{busy?'正在登录…':'登录工作空间'}}<ArrowRight :size="17"/></button><div class="login-hint"><ShieldCheck :size="17"/><span>本地演示初始账号：admin / Admin12345!<br>部署时可通过 ADMIN_PASSWORD 设置密码</span></div><a href="/docs" target="_blank" class="subtle-link">查看 API 文档 <ArrowRight :size="14"/></a></form></div>
<div v-else class="app-shell">
<aside class="sidebar"><div class="brand"><span class="brand-symbol"><Activity :size="23"/></span>Aurora<span>Test</span><small>LAB</small></div><div class="workspace-chip"><div class="workspace-icon"><Boxes :size="19"/></div><div><strong>测试工作空间</strong><small>毕业设计 · SDET Platform</small></div><ShieldCheck :size="14"/></div><div class="nav-caption">WORKSPACE</div><nav><button v-for="item in nav" :key="item.id" :aria-label="item.name" :title="item.name" :class="{active:page===item.id}" @click="navigate(item.id)"><component :is="item.icon" :size="18"/><span>{{item.name}}</span><span v-if="item.id==='cases'&&stats.pending" class="nav-count">{{stats.pending}}</span><span v-if="item.id==='ai'" class="ai-mini">AI</span><span v-if="item.id==='runs'&&activeRuns" class="pulse-dot"></span></button></nav><div class="sidebar-bottom"><div class="engine-status"><span class="status-dot"></span><span>Playwright 执行引擎</span><small>READY</small></div><a href="/docs" target="_blank"><BookOpen :size="16"/> API 接口文档 <ArrowRight :size="14"/></a><button class="account" @click="logout" title="退出登录"><span class="avatar">{{user.username.slice(0,1).toUpperCase()}}</span><span><strong>{{user.username}}</strong><small>{{labels[user.role]}}</small></span><LogOut :size="16"/></button></div></aside>
<div class="main-shell"><header class="topbar"><div class="breadcrumb">工作空间 <ChevronRight :size="14"/><strong>{{pageTitle}}</strong></div><div class="topbar-actions"><span class="env-label"><span></span>本地开发环境</span><button class="icon-btn" title="刷新数据" aria-label="刷新数据" @click="reload()"><RefreshCw :size="17" :class="{spin:loading}"/></button><a class="icon-btn" href="/docs" target="_blank" title="帮助与文档"><CircleHelp :size="18"/></a><span class="avatar small">{{user.username.slice(0,1).toUpperCase()}}</span></div></header>
<main><div class="page-heading"><div><div class="eyebrow">{{page==='overview'?'QUALITY AT A GLANCE':'AURORA / '+page.toUpperCase()}}</div><h1>{{pageTitle}}<span v-if="page==='ai'" class="badge purple">AI ASSISTED</span></h1><p>{{({overview:'从需求到证据，掌握测试质量的每一个环节。',requirements:'定义业务预期，建立可追踪的测试起点。',cases:'管理结构化用例，让每一次执行都有明确预期。',ai:'让大模型辅助设计，让规则与人工审核把关。',runs:'异步编排浏览器测试，实时追踪执行过程。',reports:'汇总执行证据，追溯需求与用例版本。',experiments:'以真实数据评估生成质量、执行能力与缺陷检出。',settings:'管理工作空间、成员权限与运行配置。'})[page]}}</p></div><div class="heading-actions"><select v-model="projectId" @change="reload()" aria-label="当前项目"><option v-for="p in projects" :value="p.id" :key="p.id">{{p.name}}</option><option v-if="!projects.length" value="">暂无项目</option></select><button v-if="canWrite" class="btn primary" @click="page==='overview'||page==='runs'?open('run'):page==='cases'?open('case'):page==='requirements'?open('requirement'):page==='experiments'?open('experiment'):open('project')"><Plus :size="17"/>{{page==='overview'||page==='runs'?'新建测试任务':page==='cases'?'新建用例':page==='requirements'?'新增需求':page==='experiments'?'记录实验':'新建项目'}}</button></div></div>

<template v-if="page==='overview'">
<div class="welcome-banner"><div class="banner-text"><span class="badge banner-badge"><Zap :size="12"/> INTELLIGENT TESTING WORKSPACE</span><h2>把重复交给自动化，把判断留给你。</h2><p>AI 生成候选用例，人工审核后执行。每个结果，都有迹可循。</p><button @click="navigate('ai')">开始 AI 辅助设计 <ArrowRight :size="16"/></button></div><div class="banner-art" aria-hidden="true"><div class="orbit o1"></div><div class="orbit o2"></div><div class="art-card art-back"><Code2 :size="22"/><i></i><i></i><i></i></div><div class="art-card art-front"><span class="art-check"><CheckCheck :size="25"/></span><strong>验证每一种可能</strong><small>GENERATE · REVIEW · EXECUTE</small><div class="art-bars"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div></div><span class="sparkle s1">✦</span><span class="sparkle s2">✦</span></div></div>
<div class="metric-grid"><article class="metric-card"><div class="metric-top"><span>测试用例总数</span><span class="metric-icon violet"><ClipboardCheck :size="18"/></span></div><div class="metric-value">{{stats.cases||0}}<small>条</small></div><div class="metric-foot"><span class="tiny-dot violet-bg"></span>{{stats.approved||0}} 条已审核通过<span class="muted">/ {{stats.pending||0}} 条待审核</span></div></article><article class="metric-card"><div class="metric-top"><span>累计执行任务</span><span class="metric-icon blue"><CirclePlay :size="18"/></span></div><div class="metric-value">{{stats.runs||0}}<small>次</small></div><div class="metric-foot"><span class="tiny-dot blue-bg"></span>{{activeRuns}} 个任务正在队列中</div></article><article class="metric-card"><div class="metric-top"><span>用例执行通过率</span><span class="metric-icon green"><ShieldCheck :size="18"/></span></div><div class="metric-value">{{stats.pass_rate==null?'—':stats.pass_rate}}<small v-if="stats.pass_rate!=null">%</small></div><div class="metric-foot"><span class="tiny-dot green-bg"></span>{{stats.passed||0}} 次通过<span class="muted">/ {{stats.failed||0}} 次失败</span></div></article><article class="metric-card"><div class="metric-top"><span>需求点覆盖率</span><span class="metric-icon amber"><GitBranch :size="18"/></span></div><div class="metric-value">{{stats.coverage||0}}<small>%</small></div><div class="metric-foot"><span class="tiny-dot amber-bg"></span>{{stats.covered_points||0}} / {{stats.requirement_points||0}} 个需求点已关联审核用例</div></article></div>
<div class="charts-grid"><section class="panel trend-panel"><div class="panel-head"><div><h3>测试执行趋势</h3><p>最近 10 次任务的用例通过率</p></div><span class="legend"><i class="tiny-dot violet-bg"></i> 通过率</span></div><div v-if="stats.trend?.length" class="line-chart"><div class="chart-labels"><span>100%</span><span>50%</span><span>0%</span></div><svg viewBox="0 0 660 180" preserveAspectRatio="none" role="img" aria-label="最近测试任务通过率趋势"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#7160e8" stop-opacity=".16"/><stop offset="100%" stop-color="#7160e8" stop-opacity="0"/></linearGradient></defs><path d="M40 40 H640 M40 95 H640 M40 150 H640" stroke="#eef0f5" stroke-dasharray="4 5" fill="none"/><polygon :points="`50,160 ${chartPoints} ${stats.trend.length===1?50:630},160`" fill="url(#fill)"/><polyline :points="chartPoints" fill="none" stroke="#7462e8" stroke-width="3" stroke-linejoin="round"/><circle v-for="(r,i) in stats.trend" :key="i" :cx="50+i*(580/Math.max(stats.trend.length-1,1))" :cy="150-(r.passed/(r.passed+r.failed||1))*110" r="4" fill="white" stroke="#7462e8" stroke-width="2"/></svg><div class="chart-x"><span v-for="(r,i) in stats.trend" :key="i">{{date(r.created_at).split(' ')[0]}}</span></div></div><div v-else class="empty chart-empty"><Activity :size="34"/><strong>等待第一次真实执行</strong><span>审核用例并创建任务后，将自动生成趋势。</span><button class="text-btn" @click="navigate('cases')">去审核用例 <ArrowRight :size="14"/></button></div></section><section class="panel distribution"><div class="panel-head"><div><h3>执行结果分布</h3><p>累计实际执行结果</p></div><Gauge :size="17" class="muted"/></div><div class="donut-layout"><div class="donut" :style="donutStyle"><div><strong>{{stats.executed||0}}</strong><small>用例执行次数</small></div></div><div class="donut-legend"><div><i class="tiny-dot violet-bg"></i>通过<strong>{{stats.passed||0}}</strong></div><div><i class="tiny-dot coral-bg"></i>失败<strong>{{stats.failed||0}}</strong></div><div><i class="tiny-dot gray-bg"></i>跳过<strong>{{(stats.executed||0)-(stats.passed||0)-(stats.failed||0)}}</strong></div></div></div><div class="panel-note"><ShieldCheck :size="14"/>统计来自浏览器真实执行与持久化记录</div></section></div>
<div class="bottom-grid"><section class="panel"><div class="panel-head"><div><h3>最近测试任务 <span class="count-label">{{stats.runs||0}}</span></h3><p>查看执行进展与测试证据</p></div><button class="text-btn" @click="navigate('runs')">查看全部 <ArrowRight :size="14"/></button></div><div class="table-wrap"><table><thead><tr><th>任务名称</th><th>状态</th><th>通过 / 总数</th><th>创建时间</th><th></th></tr></thead><tbody><tr v-for="r in stats.recent_runs" :key="r.id" class="clickable" @click="runDetail(r)"><td><div class="name-cell"><span class="table-icon"><CirclePlay :size="16"/></span><div><strong>{{r.name}}</strong><small>#{{r.id.slice(0,8)}} · {{r.browser}}</small></div></div></td><td><span :class="['badge',r.status]"><i></i>{{labels[r.status]}}</span></td><td>{{r.summary.passed||0}} <span class="muted">/ {{r.summary.total}}</span></td><td class="muted">{{date(r.created_at)}}</td><td><ChevronRight :size="16"/></td></tr><tr v-if="!stats.recent_runs?.length"><td colspan="5"><div class="empty table-empty"><CirclePlay :size="25"/><span>还没有测试任务。先审核用例，再开始执行。</span></div></td></tr></tbody></table></div></section><section class="panel workflow-panel"><div class="panel-head"><div><h3>你的测试闭环</h3><p>从业务需求到可验证证据</p></div><GitBranch :size="17" class="muted"/></div><button v-for="(w,i) in [{name:'定义需求',sub:'拆解业务场景与需求点',page:'requirements',icon:FileText},{name:'智能生成',sub:'规则约束 + 结构化输出',page:'ai',icon:Sparkles},{name:'人工审核',sub:'校验预期与版本留痕',page:'cases',icon:ShieldCheck},{name:'执行与复盘',sub:'浏览器实测 · 截图 · Trace',page:'runs',icon:CirclePlay}]" :key="w.page" class="workflow-row" @click="navigate(w.page)"><span class="workflow-icon"><component :is="w.icon" :size="17"/></span><span><strong>{{w.name}}</strong><small>{{w.sub}}</small></span><ChevronRight :size="15"/></button></section></div>
</template>

<template v-if="page==='requirements'"><div class="info-strip"><GitBranch :size="18"/><span>需求点是用例覆盖和实验评价的基准。创建后保留原始描述，避免历史运行的追踪关系漂移。</span></div><div v-if="!requirements.length" class="panel empty"><FileText/><strong>创建你的第一份需求</strong><span>将业务描述拆解为带编号的需求点。</span></div><article v-for="r in requirements" :key="r.id" class="panel requirement-card"><div class="panel-head"><div class="name-cell"><span class="metric-icon violet"><FileText :size="20"/></span><div><h3>{{r.title}}</h3><p>{{date(r.created_at)}} · {{r.points.length}} 个需求点</p></div></div><button class="btn secondary" @click="genForm.requirement_id=r.id;navigate('ai')"><Sparkles :size="15"/>生成候选用例</button></div><p class="requirement-content">{{r.content}}</p><div class="requirement-points"><div v-for="point in r.points" :key="point.id"><span class="point-id">{{point.id}}</span><span>{{point.text}}</span><span class="badge neutral">{{cases.filter(c=>c.requirement_id===r.id&&c.body.requirement_points.includes(point.id)).length}} 条用例</span></div></div></article></template>

<template v-if="page==='cases'"><div class="panel"><div class="toolbar"><div class="tabs"><button v-for="s in ['all','pending','approved','rejected']" :class="{active:caseFilter===s}" :key="s" @click="caseFilter=s;selected=[]">{{s==='all'?'全部用例':labels[s]}} <span>{{s==='all'?cases.length:cases.filter(c=>c.status===s).length}}</span></button></div><label class="search-field"><Search :size="16"/><input v-model="query" placeholder="搜索用例标题 / 需求编号" aria-label="搜索测试用例"></label></div><div v-if="selected.length" class="selection-bar"><span>已选择 {{selected.length}} 条审核用例</span><button class="text-btn" @click="open('run')">创建执行任务 <ArrowRight :size="14"/></button></div><div class="table-wrap"><table><thead><tr><th class="check-cell"><input type="checkbox" aria-label="选择全部已审核用例" @change="toggleAll"></th><th>测试用例</th><th>需求点</th><th>优先级</th><th>审核状态</th><th>版本</th><th>操作</th></tr></thead><tbody><tr v-for="c in filteredCases" :key="c.id"><td><input type="checkbox" v-model="selected" :value="c.id" :disabled="c.status!=='approved'" :aria-label="'选择 '+c.body.title"></td><td><button class="table-title" @click="open('case',c)">{{c.body.title}}</button><small class="cell-sub">{{c.body.scenario}} · {{c.generation_id?'智能辅助生成':'人工设计'}}</small></td><td><span v-for="p in c.body.requirement_points" :key="p" class="code-tag">{{p}}</span></td><td><span :class="['priority',c.body.priority]">{{c.body.priority}}</span></td><td><span :class="['badge',c.status]"><i></i>{{labels[c.status]}}</span></td><td class="muted">v{{c.version}}</td><td><button v-if="canReview&&c.status==='pending'" class="text-btn" @click="open('review',c)">审核 <ChevronRight :size="13"/></button><button v-else class="text-btn muted" @click="open('case',c)">详情</button></td></tr><tr v-if="!filteredCases.length"><td colspan="7"><div class="empty"><ClipboardCheck/><strong>没有符合条件的用例</strong><span>创建用例或前往 AI 用例生成。</span></div></td></tr></tbody></table></div><div class="table-footer"><span>共 {{filteredCases.length}} 条用例 · 仅审核通过的版本可以执行</span><span>JSON Schema 校验已启用 <ShieldCheck :size="13"/></span></div></div></template>

<template v-if="page==='ai'"><div class="info-strip"><ShieldCheck :size="18"/><span>AI 是测试辅助组件。所有输出都需字段校验、重复检查与人工审核，才可进入正式执行集合。</span></div><div class="ai-grid"><section class="panel"><div class="panel-head"><div><h3><span class="step-number">01</span> 配置生成任务</h3><p>选择需求与生成方式</p></div><Sparkles :size="18" class="purple-text"/></div><form class="padded-form" @submit.prevent="generate"><label>关联需求<select v-model="genForm.requirement_id" aria-label="关联需求" required><option v-for="r in requirements" :key="r.id" :value="r.id">{{r.title}}</option></select></label><div class="requirement-preview"><span class="mini-label">需求上下文</span><p>{{genReq?.content||'请先在需求管理中创建需求。'}}</p><div><span v-for="p in genReq?.points" :key="p.id" class="code-tag">{{p.id}}</span></div></div><label>生成方式</label><label v-for="method in ['rules','direct_llm','constrained_llm']" :key="method" :class="['method-choice',{chosen:genForm.method===method}]"><input type="radio" :value="method" v-model="genForm.method"><span><strong>{{labels[method]}}</strong><small>{{method==='rules'?'可复现的固定模板，用作实验对照':method==='direct_llm'?'基础结构提示，用于直接调用对照':'测试设计规则 + Schema + 语义化定位约束'}}</small></span><Sparkles v-if="method==='constrained_llm'" :size="16"/></label><div class="inline-fields"><label>候选用例数<input type="number" v-model.number="genForm.count" min="1" max="20" required></label><div class="field-note"><span class="status-dot" :class="{offline:!config.llm_configured}"></span>{{config.llm_configured?'模型接口已配置':'模型未配置，可使用规则基线'}}</div></div><button class="btn primary wide" :disabled="busy||!canWrite||!genReq"><Sparkles :size="17"/>{{busy?'正在生成与校验，请稍候…':'生成候选测试用例'}}<ArrowRight :size="16"/></button><small class="muted">生成不会自动批准用例。相同脚本与需求点会被去重。</small></form></section><section class="panel generation-output"><div class="panel-head"><div><h3><span class="step-number">02</span> 结构校验与生成结果</h3><p>保留模型、Prompt、原始响应和输入哈希</p></div><Code2 :size="18" class="muted"/></div><template v-if="generationResult"><div class="result-summary"><span class="metric-icon green"><CheckCheck :size="22"/></span><div><h3>生成处理完成</h3><p>新增 {{generationResult.cases.length}} 条 · 校验错误 {{generationResult.generation.payload.errors.length}} 项 · 重复 {{generationResult.generation.payload.duplicates+generationResult.generation.payload.cross_duplicates}} 条</p></div></div><div class="mini-metrics"><div><strong>{{generationResult.generation.payload.raw_count}}</strong><small>原始候选</small></div><div><strong>{{generationResult.generation.payload.valid_count??generationResult.generation.payload.accepted_count}}</strong><small>结构有效</small></div><div><strong>{{duration(generationResult.generation.duration_ms)}}</strong><small>生成耗时</small></div></div><div v-for="c in generationResult.cases" :key="c.id" class="generated-case"><div><FileCheck2 :size="17"/><strong>{{c.body.title}}</strong><span class="badge pending">待审核</span></div><p>{{c.body.expected_result}}</p></div><p v-if="!generationResult.cases.length" class="padded muted">没有新增用例。可检查重复脚本或下方字段校验错误。</p><pre v-if="generationResult.generation.payload.errors.length" class="code-block error-text">{{JSON.stringify(generationResult.generation.payload.errors,null,2)}}</pre><div class="padded"><button class="btn secondary wide" @click="navigate('cases');caseFilter='pending'">前往人工审核 <ArrowRight :size="16"/></button></div><details class="raw-details"><summary>查看原始响应与生成溯源</summary><pre>{{JSON.stringify(generationResult.generation,null,2)}}</pre></details></template><div v-else class="empty generation-empty"><div class="ai-orb"><Sparkles :size="32"/></div><h3>{{busy?'正在组织测试场景…':'把需求，变成可验证的测试。'}}</h3><p>从左侧选择一份需求，开始生成。<br>我们会检查结构、关联需求点，并保留生成过程。</p><div class="schema-chips"><span><Check :size="12"/>字段校验</span><span><Check :size="12"/>重复检查</span><span><Check :size="12"/>人工审核</span></div></div></section></div><section class="panel section-gap"><div class="panel-head"><div><h3>生成记录</h3><p>可复查的提示词与模型调用轨迹</p></div><span class="count-label">{{generations.length}}</span></div><div class="table-wrap"><table><thead><tr><th>生成方式 / 模型</th><th>Prompt 版本</th><th>原始 / 有效 / 入库</th><th>耗时</th><th>生成时间</th><th></th></tr></thead><tbody><tr v-for="g in generations" :key="g.id"><td><strong>{{labels[g.method]}}</strong><small class="cell-sub">{{g.model}}</small></td><td><span class="code-tag">{{g.prompt_version}}</span></td><td>{{g.payload.raw_count}} / {{g.payload.valid_count??g.payload.accepted_count}} / {{g.payload.created_count}}</td><td>{{duration(g.duration_ms)}}</td><td class="muted">{{date(g.created_at)}}</td><td><button class="text-btn" @click="modal={type:'raw',data:g}">溯源</button></td></tr><tr v-if="!generations.length"><td colspan="6" class="center muted padded">尚无生成记录</td></tr></tbody></table></div></section></template>

<template v-if="page==='runs'"><div class="run-status-cards"><div><span class="metric-icon blue"><Clock3 :size="19"/></span><span>队列与执行中<strong>{{activeRuns}}</strong></span></div><div><span class="metric-icon green"><CheckCheck :size="19"/></span><span>已通过任务<strong>{{runs.filter(r=>r.status==='passed').length}}</strong></span></div><div><span class="metric-icon coral"><TriangleAlert :size="19"/></span><span>失败或异常任务<strong>{{runs.filter(r=>['failed','error','interrupted'].includes(r.status)).length}}</strong></span></div></div><section class="panel"><div class="panel-head"><div><h3>测试任务列表</h3><p>独立 pytest 子进程执行 · 页面自动更新活动任务</p></div><span class="badge neutral">{{runs.length}} 个任务</span></div><div class="table-wrap"><table><thead><tr><th>任务</th><th>状态</th><th>执行进度</th><th>结果</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="r in runs" :key="r.id"><td><button class="table-title" @click="runDetail(r)">{{r.name}}</button><small class="cell-sub">{{r.browser}} · 重复 {{r.repeat}} 次 · #{{r.id.slice(0,8)}}</small></td><td><span :class="['badge',r.status]"><i></i>{{labels[r.status]}}</span></td><td><div class="progress"><i :style="{width:100*(r.summary.completed||0)/(r.summary.total||1)+'%'}"></i></div><small class="muted">{{r.summary.completed||0}} / {{r.summary.total}}</small></td><td><span class="green-text">{{r.summary.passed||0}} 通过</span><span class="muted"> / </span><span :class="{'error-text':r.summary.failed}">{{r.summary.failed||0}} 失败</span></td><td class="muted">{{date(r.created_at)}}</td><td><div class="row-actions"><button class="text-btn" @click="runDetail(r)">查看详情</button><button v-if="canWrite&&['queued','running'].includes(r.status)" class="text-btn error-text" @click="cancel(r)">取消</button></div></td></tr><tr v-if="!runs.length"><td colspan="6"><div class="empty"><CirclePlay :size="32"/><strong>准备好开始一次回归测试了吗？</strong><span>选择已审核的用例，后台执行不会阻塞平台操作。</span><button v-if="canWrite" class="btn primary" @click="open('run')"><Plus :size="16"/>创建测试任务</button></div></td></tr></tbody></table></div></section></template>

<template v-if="page==='reports'"><div class="info-strip"><GitBranch :size="18"/><span>覆盖率统计已审核用例关联的需求点；最近结果保留执行时的版本。报告支持 HTML、JSON、CSV，证据需在任务详情下载。</span></div><section class="panel"><div class="panel-head"><div><h3>需求 — 用例 — 执行追踪矩阵</h3><p>{{stats.covered_points||0}} / {{stats.requirement_points||0}} 个需求点有审核用例覆盖</p></div><span class="badge purple">{{stats.coverage||0}}% 覆盖</span></div><div class="table-wrap"><table><thead><tr><th>需求点</th><th>描述</th><th>关联用例</th><th>最近执行结果</th></tr></thead><tbody><tr v-for="t in traceability" :key="t.requirement_id+t.id"><td><span class="point-id">{{t.id}}</span></td><td>{{t.text}}</td><td><div v-for="c in t.cases" :key="c.id" class="trace-case"><button class="text-btn" @click="open('case',cases.find(x=>x.id===c.id))">{{c.title}}</button><span :class="['badge',c.status]">{{labels[c.status]}}</span></div><span v-if="!t.cases.length" class="muted">尚无用例</span></td><td><button v-if="t.last_result" class="text-btn" @click="runDetail({id:t.last_result.run_id})"><span :class="['badge',t.last_result.status]">{{labels[t.last_result.status]}} · v{{t.last_result.case_version}}</span><ChevronRight :size="14"/></button><span v-else class="muted">未执行</span></td></tr><tr v-if="!traceability.length"><td colspan="4" class="center padded muted">创建需求后显示追踪矩阵</td></tr></tbody></table></div></section><section class="panel section-gap"><div class="panel-head"><div><h3>可导出测试报告</h3><p>包含运行汇总、用例版本、错误堆栈与证据元数据</p></div><FileCheck2 :size="18" class="muted"/></div><div v-for="r in runs.filter(x=>!['queued','running','cancelling'].includes(x.status))" :key="r.id" class="report-row"><span class="metric-icon violet"><FileText :size="20"/></span><div><strong>{{r.name}}</strong><small>{{date(r.created_at)}} · {{r.summary.passed||0}} / {{r.summary.total}} 通过</small></div><span :class="['badge',r.status]">{{labels[r.status]}}</span><button v-for="format in ['html','json','csv']" :key="format" class="btn secondary small-btn" @click="download('/runs/'+r.id+'/report?format='+format,`report-${r.id.slice(0,8)}.${format}`)"><ArrowDownToLine :size="13"/>{{format.toUpperCase()}}</button></div><div v-if="!runs.length" class="empty"><FileText/><span>完成测试任务后可导出报告</span></div></section></template>

<template v-if="page==='experiments'"><div class="info-strip"><FlaskConical :size="18"/><span>规则基线、直接 LLM、规则约束 + LLM 使用同一需求集与预置缺陷集。只记录实测观察值，不将缺失数据补为模型效果。</span></div><div class="experiment-methods"><article v-for="(method,i) in ['rules','direct_llm','constrained_llm']" :key="method" class="panel"><span class="mini-label">METHOD 0{{i+1}}</span><h3>{{labels[method]}}</h3><p>{{i===0?'人工设计 / 固定规则模板对照':i===1?'基础提示 + 统一结构校验':'设计规则 + 提示约束 + 统一校验'}}</p><div class="method-records"><strong>{{experiments.filter(x=>x.method===method).length}}</strong> 组真实观察记录</div></article></div><section class="panel section-gap"><div class="panel-head"><div><h3>实验观察与评价指标</h3><p>可执行率 = 可执行数 / 结构有效数；无缺陷集时检出率显示为 —</p></div><button class="btn secondary" @click="download('/experiments/export?project_id='+projectId,'experiments.csv')"><ArrowDownToLine :size="15"/>导出 CSV</button></div><div class="table-wrap"><table><thead><tr><th>实验 / 方法</th><th>需求覆盖</th><th>结构有效</th><th>可执行率</th><th>重复率</th><th>缺陷检出</th><th>修订 / 生成耗时</th><th>证据</th></tr></thead><tbody><tr v-for="e in experiments" :key="e.id"><td><strong>{{e.name}}</strong><small class="cell-sub">{{labels[e.method]}}</small></td><td>{{pct(e.metrics.coverage)}}</td><td>{{pct(e.metrics.validity)}}</td><td>{{pct(e.metrics.executability)}}</td><td>{{pct(e.metrics.duplicate_rate)}}</td><td>{{pct(e.metrics.defect_detection)}}</td><td>{{e.metrics.revision_seconds}} s / {{duration(e.metrics.generation_ms)}}</td><td><button class="text-btn" @click="modal={type:'raw',data:e}">查看</button></td></tr><tr v-if="!experiments.length"><td colspan="8"><div class="empty"><FlaskConical :size="32"/><strong>实验数据等待采集</strong><span>使用 experiments/ 中的脚本运行实验，再录入或导入真实观察值。</span></div></td></tr></tbody></table></div></section><div class="panel section-gap padded"><h3>复现路径</h3><p class="muted">运行三组生成对比、20 条批量执行、单例 20 次稳定性，以及 CSS/XPath 与语义化定位、失败日志三组分类实验。脚本与指标定义见源码 README 和 docs/实验方案.md。</p><code class="command">python experiments/collect.py --url http://127.0.0.1:8000 --suite acceptance</code></div></template>

<template v-if="page==='settings'"><div class="settings-grid"><section class="panel"><div class="panel-head"><div><h3>运行配置</h3><p>服务端环境变量管理，密钥不返回浏览器</p></div><Settings2 :size="18" class="muted"/></div><div class="settings-item"><span>数据库</span><span class="badge neutral"><Database :size="13"/>{{config.database?.toUpperCase()}}</span></div><div class="settings-item"><span>大模型接口</span><span :class="['badge',config.llm_configured?'approved':'pending']">{{config.llm_configured?'已配置':'未配置'}}</span></div><div class="settings-item"><span>模型</span><code>{{config.llm_model}}</code></div><div class="settings-item"><span>Prompt 版本</span><code>{{config.prompt_version}}</code></div><div class="padded"><p class="muted small-text">在工程根目录 .env 中配置 LLM_API_KEY、LLM_BASE_URL、LLM_MODEL 后重启。规则基线无需模型密钥。</p><p class="muted small-text">SQLite 用于快速演示；Docker Compose 默认使用 MySQL 8。生产运行采用单 API 实例与单队列调度器。</p></div></section><section class="panel"><div class="panel-head"><div><h3>项目设置</h3><p>所有成员共享当前平台项目，权限按角色控制</p></div><FolderKanban :size="18" class="muted"/></div><div v-for="p in projects" :key="p.id" class="project-setting"><span class="metric-icon violet"><FolderKanban :size="18"/></span><div><strong>{{p.name}}</strong><small>{{p.base_url}}</small></div><button v-if="canWrite" class="text-btn" @click="open('project',p)">编辑</button></div><div class="padded"><a href="/demo/" class="btn secondary" target="_blank">打开演示被测系统 <ArrowRight :size="14"/></a></div></section></div><section v-if="user.role==='admin'" class="panel section-gap"><div class="panel-head"><div><h3>成员与角色</h3><p>测试工程师可编辑与执行；审核员可批准；只读成员可查阅</p></div><button class="btn secondary" @click="open('user')"><Plus :size="15"/>新增成员</button></div><table><thead><tr><th>成员</th><th>角色</th><th>创建时间</th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td>{{u.username}}</td><td><span class="badge neutral">{{labels[u.role]}}</span></td><td class="muted">{{date(u.created_at)}}</td></tr></tbody></table></section><section v-if="user.role==='admin'" class="panel section-gap"><div class="panel-head"><div><h3>审计日志</h3><p>记录变更、审核、生成与执行操作</p></div><button class="text-btn" @click="api('/audit').then(x=>audits=x)">刷新</button></div><div class="audit-list"><div v-for="a in audits.slice(0,30)" :key="a.id"><code>{{a.action}}</code><span class="muted">{{a.entity_id.slice(0,12)}}</span><small>{{date(a.created_at)}}</small></div><p v-if="!audits.length" class="muted padded">暂无操作记录</p></div></section></template>
<footer class="page-footer"><span><Activity :size="13"/> Aurora Test <i>v1.0</i></span><span>可审核 · 可验证 · 可追溯 <span class="footer-dot">·</span> Playwright × pytest × LLM</span></footer>
</main></div>
</div>

<div v-if="modal&&user" class="modal-backdrop" @click.self="!busy&&(modal=null)"><section :class="['modal',{'modal-wide':['case','runDetail','raw'].includes(modal.type)}]" role="dialog" aria-modal="true" :aria-label="({project:'项目设置',requirement:'新增需求',case:'用例详情',review:'人工审核',run:'新建测试任务',runDetail:'任务详情',raw:'数据溯源',user:'新增成员',experiment:'记录实验'})[modal.type]"><div class="modal-head"><div><h2>{{({project:'项目设置',requirement:'新增需求',case:modal.data?'用例详情与版本':'新建测试用例',review:'人工审核候选用例',run:'新建测试任务',runDetail:detail?.name,raw:'数据与生成溯源',user:'新增成员',experiment:'记录真实实验观察'})[modal.type]}}</h2><p v-if="modal.type==='case'">编辑已审核用例会生成新版本，并重新进入待审核状态。</p><p v-if="modal.type==='runDetail'">#{{detail?.id.slice(0,8)}} · {{detail?.browser}} · 创建于 {{date(detail?.created_at)}}</p></div><button class="icon-btn" aria-label="关闭弹窗" :disabled="busy" @click="modal=null"><X :size="20"/></button></div>
<form v-if="!['runDetail','raw'].includes(modal.type)" @submit.prevent="submit" class="modal-body">
<template v-if="modal.type==='project'"><label>项目名称<input v-model="form.name" required maxlength="120"></label><label>描述<textarea v-model="form.description" rows="3"></textarea></label><label>被测系统地址<input v-model="form.base_url" type="url" required placeholder="http://127.0.0.1:8000"></label><p class="muted small-text">脚本 goto 路径会追加到该地址。Docker 演示使用容器内地址 http://127.0.0.1:8000。</p></template>
<template v-if="modal.type==='requirement'"><label>需求标题<input v-model="form.title" required maxlength="200"></label><label>业务描述<textarea v-model="form.content" required rows="5" placeholder="写出正常、异常场景和明确的预期行为"></textarea></label><label>需求点（每行：编号 | 描述）<textarea v-model="form.points" required rows="5" placeholder="REQ-001 | 有效账号应登录成功"></textarea></label></template>
<template v-if="modal.type==='case'"><template v-if="modal.data"><div class="case-detail-summary"><h3>{{modal.data.body.title}}</h3><span :class="['badge',modal.data.status]">{{labels[modal.data.status]}} · v{{modal.data.version}}</span></div><p><strong>预期结果：</strong>{{modal.data.body.expected_result}}</p><p class="muted">前置条件：{{modal.data.body.preconditions}}</p></template><label v-if="!modal.data">关联需求<select v-model="form.requirement_id" required><option v-for="r in requirements" :key="r.id" :value="r.id">{{r.title}}</option></select></label><label>结构化用例（JSON）<textarea class="json-editor" v-model="editText" rows="19" required :readonly="!canWrite" spellcheck="false"></textarea></label><label v-if="canWrite&&modal.data">修改说明<input v-model="form.note" placeholder="说明预期、测试数据或脚本的修改原因"></label><details v-if="history.length" class="history"><summary>版本与审核历史（{{history.length}}）</summary><div v-for="h in history" :key="h.id"><strong>v{{h.version}} · {{labels[h.action]||h.action}}</strong><small>{{date(h.created_at)}} · {{h.note}}</small><details><summary>版本快照</summary><pre>{{JSON.stringify(h.body,null,2)}}</pre></details></div></details></template>
<template v-if="modal.type==='review'"><div class="review-content"><span class="point-id">{{modal.data.body.requirement_points.join(' / ')}}</span><h3>{{modal.data.body.title}}</h3><p><strong>前置条件：</strong>{{modal.data.body.preconditions}}</p><ol><li v-for="(s,i) in modal.data.body.steps" :key="i">{{s}}</li></ol><p><strong>预期：</strong>{{modal.data.body.expected_result}}</p><pre>{{JSON.stringify(modal.data.body.test_data,null,2)}}</pre><details><summary>检查可执行脚本（{{modal.data.body.script.length}} 步）</summary><pre>{{JSON.stringify(modal.data.body.script,null,2)}}</pre></details></div><div class="review-options"><label><input type="radio" v-model="form.decision" value="approved">审核通过</label><label><input type="radio" v-model="form.decision" value="rejected">驳回修改</label></div><label>审核意见<textarea v-model="form.note" required rows="3" placeholder="请核对业务预期、数据与脚本映射，并记录审核依据"></textarea></label><p class="small-text muted">本次审核将记录审核人、用例快照和版本号。请查看脚本后作出决定。</p></template>
<template v-if="modal.type==='run'"><label>任务名称<input v-model="form.name" required maxlength="160"></label><div class="inline-fields"><label>浏览器<select v-model="form.browser"><option>chromium</option><option>firefox</option><option>webkit</option></select></label><label>重复次数<input v-model.number="form.repeat" type="number" min="1" max="20" required></label></div><label>选择已审核用例（{{form.case_ids.length}} 条）</label><div class="case-picker"><label v-for="c in approved" :key="c.id"><input type="checkbox" v-model="form.case_ids" :value="c.id"><span>{{c.body.title}}<small>v{{c.version}} · {{c.body.requirement_points.join(', ')}}</small></span></label><p v-if="!approved.length" class="muted padded">暂无审核通过的用例，请先前往测试用例页面完成审核。</p></div><div class="info-strip small-text"><Clock3 :size="16"/>共 {{form.case_ids.length*form.repeat}} 次执行。任务会先入队，在后台真实运行。</div></template>
<template v-if="modal.type==='user'"><label>用户名<input v-model="form.username" required maxlength="64" autocomplete="off"></label><label>初始密码<input v-model="form.password" type="password" minlength="10" required autocomplete="new-password"></label><label>角色<select v-model="form.role"><option v-for="r in ['tester','reviewer','viewer','admin']" :key="r" :value="r">{{labels[r]}}</option></select></label></template>
<template v-if="modal.type==='experiment'"><label>实验名称<input v-model="form.name" required placeholder="例如：登录需求集 第 1 次"></label><label>方法<select v-model="form.method"><option v-for="m in ['rules','direct_llm','constrained_llm']" :key="m" :value="m">{{labels[m]}}</option></select></label><div class="experiment-inputs"><label v-for="(name,key) in {requirement_total:'需求点总数',covered_points:'已覆盖需求点',generated:'生成条数',valid:'结构有效条数',executable:'可执行条数',duplicates:'重复条数',defects_total:'预置缺陷总数',defects_detected:'检出缺陷数',revision_seconds:'人工修订耗时（秒）',generation_ms:'生成耗时（毫秒）'}" :key="key">{{name}}<input type="number" v-model.number="form[key]" :min="['requirement_total','generated'].includes(key)?1:0" :step="key==='revision_seconds'?'0.1':'1'" required></label></div><label>证据引用<input v-model="form.evidence_ref" required placeholder="填写生成ID、运行ID或采集数据文件路径"></label></template>
<div class="modal-actions"><button type="button" class="btn secondary" :disabled="busy" @click="modal=null">取消</button><button v-if="canWrite" class="btn primary" :disabled="busy||(modal.type==='run'&&!form.case_ids.length)"><component :is="modal.type==='run'?CirclePlay:Check" :size="16"/>{{busy?'正在处理…':modal.type==='review'?'提交审核决定':modal.type==='run'?'创建并执行':modal.type==='case'&&modal.data?'保存为新版本':'保存'}}</button></div>
</form>
<div v-if="modal.type==='raw'" class="modal-body"><pre class="raw-pre">{{JSON.stringify(modal.data,null,2)}}</pre></div>
<div v-if="modal.type==='runDetail'&&detail" class="run-detail"><div class="run-detail-top"><span :class="['badge',detail.status]"><i></i>{{labels[detail.status]}}</span><span>{{detail.summary.completed||0}} / {{detail.summary.total}} 已完成</span><span class="green-text">{{detail.summary.passed||0}} 通过</span><span class="error-text">{{detail.summary.failed||0}} 失败</span><button class="text-btn" @click="download('/runs/'+detail.id+'/report?format=html','report-'+detail.id.slice(0,8)+'.html')"><ArrowDownToLine :size="14"/>HTML 报告</button></div><div v-if="detail.summary.error" class="error-banner">{{detail.summary.error}}</div><div class="result-layout"><div class="result-list"><button v-for="r in detail.results" :key="r.id" :class="{active:selectedResult?.id===r.id}" @click="selectedResult=r"><Check v-if="r.status==='passed'" :size="17" class="green-text"/><XCircle v-else :size="17" class="error-text"/><span><strong>{{r.ordinal}}. {{r.evidence.title}}</strong><small>v{{r.evidence.case_version}} · {{duration(r.duration_ms)}}</small></span></button><div v-if="!detail.results.length" class="empty"><Clock3/><span>{{['queued','running'].includes(detail.status)?'等待浏览器执行结果…':'暂无执行结果'}}</span></div></div><div v-if="selectedResult" class="result-content"><h3>{{selectedResult.evidence.title}}</h3><div class="evidence-toolbar"><button v-if="selectedResult.evidence.screenshot" class="btn secondary small-btn" @click="download('/runs/'+detail.id+'/artifacts/'+selectedResult.evidence.screenshot,selectedResult.evidence.screenshot)"><ArrowDownToLine :size="14"/>失败截图</button><button v-if="selectedResult.evidence.trace" class="btn secondary small-btn" @click="download('/runs/'+detail.id+'/artifacts/'+selectedResult.evidence.trace,selectedResult.evidence.trace)"><ArrowDownToLine :size="14"/>Trace</button><button class="text-btn" @click="download('/runs/'+detail.id+'/artifacts/pytest.log','pytest.log')">执行日志</button><button class="text-btn" @click="download('/runs/'+detail.id+'/artifacts/junit.xml','junit.xml')">JUnit</button></div><h4>执行步骤</h4><div v-for="(s,i) in selectedResult.evidence.steps" :key="i" class="execution-step"><span :class="s.status==='passed'?'green-text':'error-text'">{{s.status==='passed'?'✓':'×'}}</span><code>{{s.index}}. {{s.action}}</code><span class="muted">{{s.locator?.value}}</span><small>{{duration(s.duration_ms)}}</small></div><pre v-if="selectedResult.evidence.error" class="error-log">{{selectedResult.evidence.error}}</pre><p v-else class="success-notice"><CheckCheck :size="17"/>所有步骤与断言均已通过。</p><div v-if="selectedResult.status==='failed'" class="analysis-section"><h4><Sparkles :size="16"/>失败辅助分析</h4><div class="inline-fields"><select v-model="analysisMethod" aria-label="分析方法"><option v-for="m in ['rules','direct_llm','constrained_llm']" :key="m" :value="m">{{labels[m]}}</option></select><button class="btn primary small-btn" :disabled="busy||!canWrite" @click="analyzeResult">{{busy?'分析中…':'分析失败日志'}}</button></div><div v-if="selectedResult.analysis" class="analysis-output"><span class="badge purple">{{selectedResult.analysis.category}}</span><p>{{selectedResult.analysis.candidate_cause}}</p><small>{{selectedResult.analysis.disclaimer}} · {{selectedResult.analysis.model}}</small><details><summary>分析溯源</summary><pre>{{JSON.stringify(selectedResult.analysis,null,2)}}</pre></details></div><p v-else class="muted small-text">分析只提供候选原因，请结合错误堆栈、截图和 Trace 复核。</p></div></div><div v-else class="empty"><Terminal :size="30"/><span>选择一条结果查看执行证据</span></div></div></div>
</section></div>
<Transition name="toast"><div v-if="toast" :class="['toast-message',{error:toast.error}]" role="status"><TriangleAlert v-if="toast.error" :size="18"/><CheckCheck v-else :size="18"/><span>{{toast.message}}</span><button class="icon-btn" aria-label="关闭通知" @click="toast=null"><X :size="15"/></button></div></Transition>
</template>
